// 非阻塞I/O示例
const fs = require('fs');

// 异步读取（非阻塞）
fs.readFile('/path/to/file', (err, data) => {
  if (err) throw err;
  console.log(data);
});
console.log('继续执行...'); // 先于readFile回调执行

// Stream流处理
const { createReadStream, createWriteStream } = require('fs');
const { createGzip } = require('zlib');
const { pipeline } = require('stream');

// 使用pipeline处理流
pipeline(
  createReadStream('input.txt'),
  createGzip(),
  createWriteStream('input.txt.gz'),
  (err) => {
    if (err) console.error('Pipeline failed:', err);
    else console.log('Pipeline succeeded');
  }
);

// 自定义Transform流
const { Transform } = require('stream');

class UpperTransform extends Transform {
  _transform(chunk, encoding, callback) {
    this.push(chunk.toString().toUpperCase());
    callback();
  }
}

process.stdin
  .pipe(new UpperTransform())
  .pipe(process.stdout);

// Buffer操作
const buf = Buffer.from('Hello');
console.log(buf); // <Buffer 48 65 6c 6c 6f>
console.log(buf.toString()); // 'Hello'
console.log(buf.toString('base64')); // 'SGVsbG8='

// 高水位和背压
const readable = createReadStream('large.txt');
const writable = createWriteStream('output.txt');

readable.on('data', (chunk) => {
  const canWrite = writable.write(chunk);
  if (!canWrite) {
    readable.pause(); // 背压：暂停读取
    writable.once('drain', () => readable.resume());
  }
});

// process.nextTick vs setImmediate
process.nextTick(() => console.log('nextTick')); // 当前阶段后立即执行
setImmediate(() => console.log('immediate'));   // check阶段执行
// nextTick优先级高于setImmediate
